    private Set<Pet> pets;

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    /**
     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
     * Derived from the owner's own fields, so it stays consistent with them.
     */
    @Transient
    public String getMembershipNumber() {
        if (this.customerCode == null || this.registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
    }

    /**
     * The owner's membership tier: {@code "SILVER"} for a unique owner (namesake
     * count of zero) who has an email on file, and {@code "BRONZE"} otherwise.
     * Derived from the owner's own fields, so it stays consistent with them.
     */
    @Transient
    public String getMembershipTier() {
        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        return unique && hasEmail ? "SILVER" : "BRONZE";
    }

    /**
     * The owner's locality: the canonical region derived from the city via the fixed
     * {@link CityRegionTable}, or {@code "UNKNOWN"} when the city is not in the table.
     * Derived from the owner's own city, so it stays consistent with it.
     */
    @Transient
    public String getLocality() {
        return CityRegionTable.regionFor(this.city);
    }

    /**
     * Normalize the registration date before persisting: default it to the server's
     * current date when none was supplied, then roll it forward onto a business day so
     * every newly persisted owner is registered on a weekday.
